#!/usr/bin/env node
// Generates ingredients.json with ~500 ingredients
// Run: node packages/db/scripts/generate-ingredients.mjs  (or `pnpm db:seed` to generate + seed)

import { writeFileSync } from 'fs';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';

const __dirname = dirname(fileURLToPath(import.meta.url));

// Shelf life defaults by category
const shelfLifeDefaults = {
  produce:   { fridge_days: 7, freezer_days: 180, pantry_days: null },
  dairy:     { fridge_days: 14, freezer_days: 90, pantry_days: null },
  protein:   { fridge_days: 3, freezer_days: 180, pantry_days: null },
  grain:     { fridge_days: null, freezer_days: null, pantry_days: 365 },
  spice:     { fridge_days: null, freezer_days: null, pantry_days: 730 },
  condiment: { fridge_days: 180, freezer_days: null, pantry_days: 365 },
  frozen:    { fridge_days: null, freezer_days: 180, pantry_days: null },
  other:     { fridge_days: null, freezer_days: null, pantry_days: 365 },
};

/**
 * Build a normalised ingredient record (the per-row factory used ~500 times below).
 * @param {string} name
 * @param {string} category - key into shelfLifeDefaults
 * @param {string} defaultUnit
 * @param {{ calories: number, protein_g: number, carbs_g: number, fat_g: number, fiber_g: number }} nutrition - per 100g
 * @param {{ aliases?: string[], tags?: string[], staple?: boolean, shelfLife?: object }} [opts]
 */
function ingredient(name, category, defaultUnit, nutrition, opts = {}) {
  return {
    name,
    aliases: opts.aliases || [],
    category,
    defaultUnit,
    nutritionPer100g: {
      calories: nutrition.calories,
      protein_g: nutrition.protein_g,
      carbs_g: nutrition.carbs_g,
      fat_g: nutrition.fat_g,
      fiber_g: nutrition.fiber_g,
    },
    shelfLife: opts.shelfLife || shelfLifeDefaults[category],
    tags: opts.tags || [],
    isPantryStaple: opts.staple || false,
  };
}

